var fcfield_image={};fcfield_image.debugToConsole=[];fcfield_image.use_native_apis=[];fcfield_image.currElement=[];fcfield_image.dialog_handle=[];fcfield_image.toggleMediaURL=function(element_id_n,config_name)
{var url=jQuery("#"+element_id_n+"_mediaurl").val();var msg_box=jQuery("#fcfield_message_box_"+element_id_n);if(url!=""&&jQuery("#"+element_id_n+"_mediaurl").closest('.fcfield-image-mediaurl-box').is(":visible"))
{msg_box.html("<span class=\"alert alert-warning fc-iblock fcpadded\">"+Joomla.JText._('FLEXI_FIELD_IMAGE_CLEAR_MEDIA_URL_FIRST')+"</span>");return;}
jQuery("#"+element_id_n+"_mediaurl").closest('.fcfield-image-mediaurl-box').slideToggle();}
fcfield_image.showUploader=function(field_name_n,config_name)
{var fnn=field_name_n.replace(/-/g,'_');var box=jQuery('#custom_'+field_name_n+'_fc_preview_msg').closest('.fcfieldval_container');box.find('.fc_files_uploader_toggle_btn').click();}
fcfield_image.clearData=function(element_id_n,config_name)
{var mediaurl=jQuery("#"+element_id_n+"_mediaurl").val('');var msg_box=jQuery("#fcfield_message_box_"+element_id_n);mediaurl.val('');msg_box.html('');fcfield_image.clearField(jQuery("#"+element_id_n+"_mediaurl").get(0),{},config_name);}
fcfield_image.fetchData=function(element_id_n,config_name)
{var msg_box=jQuery("#fcfield_message_box_"+element_id_n);var url=jQuery("#"+element_id_n+"_mediaurl").val();if(url=="")
{msg_box.html("<span class=\"alert alert-warning fc-iblock fcpadded\">"+Joomla.JText._('FLEXI_FIELD_IMAGE_ENTER_MEDIA_URL')+"</span>");return;}
else
{msg_box.html("");}
fcfield_image.debugToConsole[config_name]?window.console.log("Fetching "+url):"";var ajax_url;var ajax_type;ajax_url="https://noembed.com/embed?url="+encodeURIComponent(url);ajax_type="jsonp";var mediaID="";var apiType="";jQuery.ajax({url:ajax_url,dataType:ajax_type,success:function(data){fcfield_image.debugToConsole[config_name]?window.console.log("Received Server response"):"";var response;try{response=typeof data!=="object"?jQuery.parseJSON(data):data;fcfield_image.debugToConsole[config_name]?window.console.log("Calling callback "+(apiType?apiType:"embedly")+" function on data:"):"";fcfield_image.debugToConsole[config_name]?window.console.log(response):"";if(mediaID&&apiType)
{switch(apiType)
{case"youtube":fcfield_image.youtubeCallback(element_id_n,response,mediaID,config_name);break;case"vimeo":fcfield_image.vimeoCallback(element_id_n,response,mediaID,config_name);break;case"dailymotion":fcfield_image.dailymotionCallback(element_id_n,response,mediaID,config_name);break;}}
else
{if(typeof response.error!=="undefined")
{msg_box.html("<span class=\"alert alert-info fc-iblock fcpadded\">Reply: "+response.error+" <br>This link is a not video / media URL ?</span>");}
else
{jQuery("#"+element_id_n+"_mediathumburl").val(response.thumbnail_url);fcfield_image.clearField(jQuery("#"+element_id_n+"_mediaurl").get(0),{},config_name);var filename=response.thumbnail_url;var preview_url=response.thumbnail_url;var preview_caption=Joomla.JText._('FLEXI_FIELD_MEDIA_URL');fcfield_image.assignImage(element_id_n,filename,preview_url,2,preview_caption,config_name);}}}catch(err){msg_box.html("<span class=\"alert alert-error alert-danger fc-iblock fcpadded\">"+Joomla.JText._('FIELDS_IMAGE_RESPONSE_PARSING_FAILED')+": "+err.message+"</span>");}},error:function(jqXHR,textStatus,errorThrown){fcfield_image.debugToConsole[config_name]?window.console.log("Error, responseText is:"):"";fcfield_image.debugToConsole[config_name]?window.console.log(jqXHR.responseText):"";var response;try{response=jQuery.parseJSON(jqXHR.responseText);}catch(err){response=jqXHR.responseText;}
var errorText=typeof response!=="object"?response:(mediaID&&(apiType=="dailymotion"||apiType=="youtube")?response.error.message:response.error_message);if(apiType=="youtube"&&typeof response=="object")errorText+=" Reason: "+response.error.errors[0].reason;msg_box.html("<span class=\"alert alert-error alert-danger fc-iblock fcpadded\"><i>"+Joomla.JText._('FIELDS_IMAGE_SERVER_RESPONDED_WITH_ERROR')+"</i><br/><br/>"+errorText+"</span>");}});}
fcfield_image.update_path_tip=function(el)
{var tipped_elements=jQuery(el).closest('.fc-field-props-box').find('.hasTipImgpath, .hasTipPreview');tipped_elements.each(function()
{var title=this.get('title')||this.get('value');if(title)
{var parts=title.split('::',2);this.store('tip:title',parts[0]);this.store('tip:text',parts[1]);}});}
fcfield_image.incrementValCnt=function(config_name)
{var box=jQuery('#'+fcfield_image.currElement[config_name]).closest('.fcfieldval_container');var hasValue=box.find('.hasvalue').val();box.find('.hasvalue').val('1');var valcounter=document.getElementById('custom_'+config_name);if(hasValue=='')
{valcounter.value=valcounter.value==''?'1':parseInt(valcounter.value)+1;}}
fcfield_image.clearFieldUploader=function(box,config_name)
{var upload_container=box.find('.fc_file_uploader');var upload_instance=upload_container.data('plupload_instance');var upBTN=box.find('.fc_files_uploader_toggle_btn');if(upload_instance)
{jQuery(upload_instance).data('fc_plupload_instance').clearUploader(upBTN.data('rowno'));}
upBTN.removeClass('active');upload_container.hide();}
fcfield_image.clearField=function(el,options,config_name)
{var box=jQuery(el).closest('.fcfieldval_container');var hasValue=box.find('.hasvalue').val();var valcounter=document.getElementById('custom_'+config_name);options=options||{};options.hide_image=options.hide_image||false;options.keep_props=options.keep_props||false;if(options.hide_image)
{box.find('.fcfield_preview_box').hide();}
else
{fcfield_image.clearFieldUploader(box,config_name);box.find('.originalname').val('');box.find('.existingname').val('');box.find('.hasvalue').val('');box.find('.fc_preview_thumb').attr('src','data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=');box.find('.fc_preview_msg').html(' ');box.find('.fcfield_preview_box').show();if(hasValue)valcounter.value=(valcounter.value==''||valcounter.value=='1')?'':parseInt(valcounter.value)-1;}
if(options.keep_props)
{box.find('input, textarea').val('');}}
fcfield_image.assignImage=function(tagid,file,preview_url,keep_modal,preview_caption,config_name)
{var ff_suffix='_existingname';var elementid_n=tagid.replace(ff_suffix,'');var valcounter=document.getElementById('custom_'+config_name);var hasvalue_obj=jQuery('#'+elementid_n);var hasValue=hasvalue_obj.val();hasvalue_obj.val(file?'1':'');if(file&&!hasValue)
{valcounter.value=valcounter.value==''?1:parseInt(valcounter.value)+1;}
else if(!file&&hasValue)
{valcounter.value=(valcounter.value==''||valcounter.value=='1')?'':parseInt(valcounter.value)-1;}
jQuery('#'+elementid_n+'_existingname').val(file);jQuery('#'+elementid_n+'_originalname').val('');var preview_img_OLD=jQuery('#'+elementid_n+'_preview_image');if(preview_img_OLD)
{var box=preview_img_OLD.closest('.fcfieldval_container');var preview_img_NEW=preview_url!=''?'<img class=\"fc_preview_thumb\" id=\"'+elementid_n+'_preview_image\" src=\"'+preview_url+'\" alt=\"Preview image\" />':'<img class=\"fc_preview_thumb\" id=\"'+elementid_n+'_preview_image\" src=\"data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=\" alt=\"Preview image\" />';preview_img_NEW=jQuery(preview_img_NEW);preview_img_NEW.insertAfter(preview_img_OLD);preview_img_OLD.remove();if(keep_modal!=2)
{preview_img_NEW.closest('.fcfield_preview_box').show();fcfield_image.clearFieldUploader(box,config_name);}
if(file)
{jQuery('#'+elementid_n+'_fc_preview_msg').html(!!preview_caption?preview_caption:file);jQuery('#'+elementid_n+'_fc_preview_msg').attr('title',!!preview_caption?file:'')}
jQuery('#'+elementid_n+'_remove').removeAttr('checked').trigger('change');}
if(!keep_modal&&!!fcfield_image.dialog_handle[config_name])
{fcfield_image.dialog_handle[config_name].dialog('close');}
jQuery(valcounter).trigger('blur');}
fcfield_image.fileFiltered=function(uploader,file,config_name)
{}
fcfield_image.fileUploaded=function(uploader,file,result,config_name)
{var _this=jQuery(uploader).data('fc_plupload_instance');try{var response=eval(result.response);}catch(err){var response=eval('('+result.response+')');}
if(!!response.error)
{alert(response.error.message);return;}
var file=response.data;file.targetid=jQuery(uploader.settings.container).closest('.fcfieldval_container').find('.existingname').attr('id');file.preview_url=jQuery(uploader.settings.container).find('.plupload_img_preview > img').attr('src');fcfield_image.assignImage(file.targetid,file.filename,file.preview_url,2,file.filename_original,config_name);}
jQuery(document).ready(function(){window.__QuantumuploadimageModalOpen=window.QuantumuploadimageModalOpen;window.QuantumuploadimageModalOpen=function(){let input=quantumuploadimageSelector.querySelector('input');let defaultSubPath=(typeof input!=='undefined'?jQuery(input).data('default-subpath'):'')||'';let defaultScope=(typeof input!=='undefined'?jQuery(input).data('default-scope'):'')||'images';defaultScope=defaultScope.replace(/^\/+|\/+$/g,'');defaultSubPath=defaultSubPath.replace(/^\/+|\/+$/g,'');let backupValue='';if(defaultScope&&defaultSubPath)
{if(input.value!=''){backupValue=input.value;jQuery(input).val('');console.log(jQuery(input).val());}
localStorage.setItem('quantummanagerLastDir','root/'+defaultSubPath);console.log(localStorage.getItem('quantummanagerLastDir'));localStorage.setItem('quantummanagerScope',defaultScope);console.log(localStorage.getItem('quantummanagerScope'));}
window.__QuantumuploadimageModalOpen();setTimeout(function(){if(backupValue)jQuery(input).val(backupValue);},200);}});